//! 🌱️ Native catalog templates retain construction frames and original population positions across turns.
use super::*;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose};
use std::mem::size_of;
#[derive(Clone,Copy)]enum Spec{Expression(&'static Expr),Name(&'static str)}
#[derive(Clone,Copy,Default)]enum Phase{#[default]Init,Aggregate,Select,AwaitAggregate,AwaitSelect,Reference}
#[derive(Default)]struct Frame{spec:Option<Spec>,phase:Phase,items:Option<Vec<V>>,index:usize,count:usize,row:usize,part:usize,member:Option<&'static str>}
pub(super)struct Template{frames:[Frame;64],depth:usize,result:Option<V>,delivered:bool,done:bool,closing:bool,retirement:RetainedCloneClose}
impl Default for Template{fn default()->Self{Self{frames:std::array::from_fn(|_|Frame::default()),depth:0,result:None,delivered:false,done:true,closing:false,retirement:Default::default()}}}
fn error()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Part21 catalog template cursor cannot transfer its native owner")}
impl Template{
 pub(super)fn start(&mut self,expression:&'static Expr)->Result<(),Fault>{if !self.terminal_is_empty(){return Err(err("Part21 template owner is still live"));}self.depth=1;self.frames[0]=Frame{spec:Some(Spec::Expression(expression)),..Default::default()};self.done=false;self.delivered=false;Ok(())}
 fn complete(&mut self,value:Option<V>){self.result=value;self.frames[self.depth-1].spec=None;self.frames[self.depth-1].phase=Phase::Init;self.depth-=1;self.delivered=true;if self.depth==0{self.done=true;}}
 fn descend(&mut self,spec:Spec){if self.depth==self.frames.len(){self.result=None;self.delivered=true;return;}self.frames[self.depth]=Frame{spec:Some(spec),..Default::default()};self.depth+=1;self.delivered=false;}
 pub(super)fn demands(&self)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands(64);}let capacity=if self.delivered&&self.depth>0&&matches!(self.frames[self.depth-1].phase,Phase::AwaitSelect){size_of::<V>()+256}else if self.depth>0{match self.frames[self.depth-1].spec{Some(Spec::Expression(expression))if expression.kind=="aggregate"=>{let count=if expression.aggregate.as_deref()==Some("ARRAY"){expression.upper.and_then(|upper|expression.lower.and_then(|lower|upper.checked_sub(lower))).and_then(|count|count.checked_add(1)).unwrap_or(0)}else{expression.lower.unwrap_or(0)};usize::try_from(count.max(0)).unwrap_or(usize::MAX).min(256)*size_of::<V>()},_=>256}}else{0};Ok(RetirementDemand{copy_bytes:4*size_of::<Frame>()+4*size_of::<V>(),capacity_bytes:capacity,depth:1,..Default::default()})}
 pub(super)fn advance(&mut self,snapshot:&Ifc2x3Snapshot,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}if self.done{return Ok(true);}let demand=self.demands()?;let grant=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return Ok(false);}let mut capacity=0;
 if self.delivered{let index=self.depth-1;match self.frames[index].phase{
 Phase::AwaitAggregate=>{if let Some(value)=self.result.take(){self.frames[index].items.as_mut().unwrap().push(value);self.frames[index].index+=1;self.frames[index].phase=Phase::Aggregate;self.delivered=false;}else{self.complete(None);}},
 Phase::AwaitSelect=>{if self.result.is_some(){let wrapped=!matches!(self.result,Some(V::Ref(_)|V::Typed{..}));let mut values=Vec::new();if wrapped{values.try_reserve_exact(1).map_err(|_|err("Part21 SELECT template allocation failed"))?;}let value=self.result.take().unwrap();let value=if !wrapped{value}else{let name=self.frames[index].member.unwrap();capacity=values.capacity()*size_of::<V>()+name.len();values.push(value);V::Typed{name:name.into(),items:values}};self.complete(Some(value));}else{self.frames[index].index+=1;self.frames[index].phase=Phase::Select;self.delivered=false;}},_=>return Err(error().into())}
 }else{let index=self.depth-1;let spec=self.frames[index].spec.ok_or_else(error)?;match self.frames[index].phase{
 Phase::Init=>match spec{
 Spec::Expression(expression)=>{if expression.kind=="aggregate"{let count=if expression.aggregate.as_deref()==Some("ARRAY"){expression.upper.and_then(|upper|expression.lower.and_then(|lower|upper.checked_sub(lower))).and_then(|count|count.checked_add(1)).unwrap_or(-1)}else{expression.lower.unwrap_or(0)};let count=usize::try_from(count.max(0)).map_err(|_|error())?;if count>256||expression.unique&&count>1||expression.item.is_none(){self.complete(None);}else{let mut values=Vec::new();values.try_reserve_exact(count).map_err(|_|err("Part21 aggregate template allocation failed"))?;capacity=values.capacity()*size_of::<V>();self.frames[index].items=Some(values);self.frames[index].count=count;self.frames[index].index=0;self.frames[index].phase=Phase::Aggregate;}}else if let Some(name)=expression.name.as_deref(){self.frames[index].spec=Some(Spec::Name(name));}else{self.complete(None);}},
 Spec::Name(name)=>{let catalog=catalog::ifc2x3_catalog();if catalog.entities.contains_key(name){self.frames[index].row=0;self.frames[index].part=0;self.frames[index].phase=Phase::Reference;}else if let Some(declaration)=catalog.types.get(name){match declaration.kind.as_str(){"enum"=>{let value=declaration.members.first().map(|member|{capacity=member.len();V::Enum(member.clone())});self.complete(value);},"select"=>{self.frames[index].index=0;self.frames[index].phase=Phase::Select;},_=>{if let Some(expression)=declaration.type_expr.as_ref(){self.frames[index].spec=Some(Spec::Expression(expression));}else{self.complete(None);}}}}else{let value=match name{"STRING"=>Some(V::Str(String::new())),"BINARY"=>{capacity=1;Some(V::Binary("0".into()))},"INTEGER"=>Some(V::Int(0)),"REAL"|"NUMBER"=>{capacity=1;Some(V::Real(Part21Decimal{negative:false,coefficient:"0".into(),scale:0,exponent:None}))},"BOOLEAN"|"LOGICAL"=>{capacity=1;Some(V::Enum("F".into()))},_=>None};self.complete(value);}}
 },
 Phase::Aggregate=>{if self.frames[index].index==self.frames[index].count{let values=self.frames[index].items.take().unwrap();self.complete(Some(V::List(values)));}else{let Spec::Expression(expression)=spec else{return Err(error().into())};let item=expression.item.as_deref().ok_or_else(error)?;self.frames[index].phase=Phase::AwaitAggregate;self.descend(Spec::Expression(item));}},
 Phase::Select=>{let Spec::Name(name)=spec else{return Err(error().into())};let declaration=catalog::ifc2x3_catalog().types.get(name).ok_or_else(error)?;if let Some(member)=declaration.members.get(self.frames[index].index){self.frames[index].member=Some(member.as_str());self.frames[index].phase=Phase::AwaitSelect;self.descend(Spec::Name(member));}else{self.complete(None);}},
 Phase::Reference=>{let Spec::Name(expected)=spec else{return Err(error().into())};let row=self.frames[index].row;let part=self.frames[index].part;if let Some(instance)=snapshot.document.instances.get(row){if let Some((name,_))=instance.entities.get(part){self.frames[index].part+=1;if name.len()<=256&&catalog::ifc2x3_is_subtype(name,expected){self.complete(Some(V::Ref(instance.id)));}}else{self.frames[index].row+=1;self.frames[index].part=0;}}else{self.complete(None);}},
 _=>return Err(error().into()),}}
 cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok(self.done)}
 pub(super)fn reset(&mut self)->Result<(),Fault>{if !self.terminal_is_empty(){return Err(err("Part21 template still owns a child"));}self.depth=0;self.delivered=false;self.done=true;self.closing=false;Ok(())}
 pub(super)fn take(&mut self)->Result<Option<V>,Fault>{if !self.done{return Err(err("Part21 template is not ready"));}self.delivered=false;Ok(self.result.take())}
 pub(super)fn begin_close(&mut self){self.closing=true;}
 pub(super)fn terminal_is_empty(&self)->bool{self.result.is_none()&&self.frames.iter().all(|frame|frame.items.is_none())&&self.retirement.is_empty()}
 pub(super)fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<V>(false,&None,body);}if self.result.is_some(){return self.retirement.next_owner_demands::<V>(true,&None,body);}self.retirement.next_owner_demands::<Vec<V>>(self.frames.iter().any(|frame|frame.items.is_some()),&None,body)}
 pub(super)fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(error());}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.result.is_some(){return self.retirement.begin_granted(&mut self.result,grant)?.ok_or_else(error);}for frame in &mut self.frames{if frame.items.is_some(){return self.retirement.begin_granted(&mut frame.items,grant)?.ok_or_else(error);}}Ok(RetainedCloneStep::Complete(Default::default()))}
}
